// Photography. Every file in assets/photos is the restaurant's own photography (from thefireside.co.za),
// exported as WebP at two widths (-800 and -1600). photos.json (generated by tools/photos.py) lists each one's
// size, and this file turns it into ready-to-use { src, srcSet, width, height, alt } objects.
import manifest from './photos.json';

const files = import.meta.glob('../assets/photos/*.webp', { eager: true, import: 'default' });
const url = (name) => files[`../assets/photos/${name}`];

export const photo = (key) => {
  const entry = manifest[key];
  if (!entry) throw new Error(`Unknown photo: ${key}`);
  const small = url(`${entry.file}-800.webp`);
  const large = url(`${entry.file}-1600.webp`) || small;
  return {
    id: key,
    src: large,
    srcSet: `${small} 800w, ${large} ${entry.width >= 1600 ? 1600 : entry.width}w`,
    width: entry.width,
    height: entry.height,
    alt: entry.alt,
    kind: entry.kind,
  };
};

export const photosOfKind = (kind) => Object.keys(manifest).filter((k) => manifest[k].kind === kind).map(photo);
export const galleryPhotos = () => Object.keys(manifest).filter((k) => manifest[k].gallery).map(photo);
